import { motion, useReducedMotionConfig } from 'motion/react';
import { X } from 'lucide-react';
import { cn } from '../../lib/cn.ts';
import { AnimatedCheckbox } from '../../vendor/spell-ui/animated-checkbox.tsx';
import { ShimmerText } from '../../vendor/spell-ui/shimmer-text.tsx';
import { Spinner } from '../../vendor/spell-ui/spinner.tsx';
import { RollingNumber } from './RollingNumber.tsx';

export type PlanStepStatus = 'pending' | 'running' | 'done' | 'error';

export interface PlanStep {
  id: string;
  label: string;
  status: PlanStepStatus;
}

export interface AnimatedPlanProps {
  steps: PlanStep[];
  title?: string;
  className?: string;
}

/** Agent plan checklist: boxes animate on completion, the running step shimmers, progress rolls. */
export function AnimatedPlan({ steps, title = 'Plan', className }: AnimatedPlanProps) {
  const reduced = useReducedMotionConfig() ?? false;
  const done = steps.filter((s) => s.status === 'done').length;
  const pct = steps.length ? (done / steps.length) * 100 : 0;
  return (
    <div
      data-fx-component="AnimatedPlan"
      data-done={done}
      data-total={steps.length}
      className={cn('flex flex-col gap-3 rounded-lg border border-border bg-card p-3 text-sm', className)}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="font-medium">{title}</span>
        <span className="tabular-nums text-xs text-muted-foreground" aria-label={`${done} of ${steps.length} steps done`}>
          <RollingNumber value={done} /> / {steps.length}
        </span>
      </div>
      <div className="h-1 overflow-hidden rounded-full bg-muted" aria-hidden="true">
        <motion.div
          className="h-full rounded-full bg-primary"
          initial={false}
          animate={{ width: `${pct}%` }}
          transition={{ duration: reduced ? 0 : 0.4, ease: 'easeOut' }}
        />
      </div>
      <ol className="flex flex-col gap-2">
        {steps.map((s) => (
          <li key={s.id} data-step={s.id} data-status={s.status} className="flex min-h-6 items-center gap-2">
            {s.status === 'running' ? (
              <>
                <span className="inline-flex size-[18px] items-center justify-center">
                  <Spinner size="sm" className="text-primary" />
                </span>
                <div className="text-sm font-medium">{reduced ? s.label : <ShimmerText delay={0}>{s.label}</ShimmerText>}</div>
              </>
            ) : s.status === 'error' ? (
              <>
                <span className="inline-flex size-[18px] items-center justify-center rounded-[6px] bg-destructive text-background">
                  <X size={12} strokeWidth={3} aria-hidden="true" />
                </span>
                <span className="text-sm font-medium text-destructive">{s.label}</span>
              </>
            ) : (
              <AnimatedCheckbox readOnly checked={s.status === 'done'} title={s.label} />
            )}
          </li>
        ))}
      </ol>
    </div>
  );
}

/**
 * Vendored from xxtomm/spell-ui (registry/spell-ui/animated-checkbox.tsx) at fffe96db7b67. MIT licence, see ../../../ATTRIBUTION.md.
 * AICL: added a controlled `checked` + `readOnly` mode (plan steps are driven by the agent, not clicked),
 * `size` of the label text, button semantics (role=checkbox, keyboard toggle) and `data-checked`.
 */
"use client";

import { motion } from "motion/react";
import { useState } from "react";
import { cn } from "../../lib/cn.ts";

interface AnimatedCheckboxProps {
  title?: React.ReactNode;
  defaultChecked?: boolean;
  /** AICL: controlled value; when given, internal state is ignored. */
  checked?: boolean;
  /** AICL: render without toggling or focus (agent-driven lists). */
  readOnly?: boolean;
  className?: string;
  onCheckedChange?: (checked: boolean) => void;
}

const springTransition = {
  type: "spring" as const,
  duration: 0.4,
  bounce: 0.2,
};

export function AnimatedCheckbox({
  title = "Implement Checkbox",
  defaultChecked = false,
  checked: controlled,
  readOnly = false,
  className,
  onCheckedChange,
}: AnimatedCheckboxProps) {
  const [inner, setInner] = useState(defaultChecked);
  const checked = controlled ?? inner;

  const toggle = () => {
    if (readOnly) return;
    const next = !checked;
    if (controlled === undefined) setInner(next);
    onCheckedChange?.(next);
  };

  return (
    <div
      role="checkbox"
      aria-checked={checked}
      aria-readonly={readOnly || undefined}
      data-checked={checked}
      tabIndex={readOnly ? -1 : 0}
      className={cn(
        "flex items-center gap-3 select-none outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-md",
        !readOnly && "cursor-pointer",
        className,
      )}
      onClick={toggle}
      onKeyDown={(e) => {
        if (e.key === " " || e.key === "Enter") {
          e.preventDefault();
          toggle();
        }
      }}
    >
      <div
        className={cn(
          "size-4.5 shrink-0 rounded-[6px] flex items-center justify-center border-[1.5px] transition-colors duration-200",
          checked
            ? "bg-foreground border-transparent"
            : "bg-transparent border-muted-foreground/40 hover:border-muted-foreground/60"
        )}
      >
        <svg viewBox="0 0 20 20" className="size-full text-background">
          <motion.path
            d="M 0 4.5 L 3.182 8 L 10 0"
            fill="transparent"
            stroke="currentColor"
            strokeWidth={1.5}
            strokeLinecap="round"
            strokeLinejoin="round"
            transform="translate(5 6)"
            initial={{ pathLength: checked ? 1 : 0, opacity: checked ? 1 : 0 }}
            animate={{
              pathLength: checked ? 1 : 0,
              opacity: checked ? 1 : 0
            }}
            transition={{
              pathLength: { ease: "easeOut", duration: 0.3 },
              opacity: { duration: 0 }
            }}
          />
        </svg>
      </div>
      <div className="relative">
        <span
          className={cn(
            "text-sm font-medium transition-colors duration-200",
            checked ? "text-muted-foreground" : "text-foreground"
          )}
        >
          {title}
        </span>
        <motion.div
          className="absolute left-0 top-1/2 h-[1.5px] bg-muted-foreground -translate-y-1/2"
          initial={{ width: checked ? "100%" : 0, opacity: checked ? 1 : 0 }}
          animate={{
            width: checked ? "100%" : 0,
            opacity: checked ? 1 : 0,
          }}
          transition={springTransition}
        />
      </div>
    </div>
  );
}

/**
 * Vendored from xxtomm/spell-ui (registry/spell-ui/shimmer-text.tsx) at fffe96db7b67. MIT licence, see ../../../ATTRIBUTION.md.
